from datetime import datetime, timezone
from typing import Any, Literal

from pydantic import BaseModel, Field


class AgenticEvent(BaseModel):
    """Telemetry event generated by an IntelliCore Agentic AI execution."""

    event_id: str

    timestamp: datetime = Field(
        default_factory=lambda: datetime.now(timezone.utc)
    )

    system_type: Literal["AGENT"] = "AGENT"

    project_id: str
    model_id: str | None = None

    trace_id: str
    span_id: str

    event_type: str

    input: Any = None
    output: Any = None

    # Common IntelliCore event latency is measured in milliseconds.
    latency: float | None = Field(
        default=None,
        description="Execution latency in milliseconds.",
        ge=0,
    )

    status: str
    error: str | None = None

    metadata: dict[str, Any] = Field(default_factory=dict)